<?php
declare(strict_types=1);
namespace Tests\Unit\Infrastructure\Cache;
use App\Domain\Auth\User\Email;use App\Domain\Auth\User\PasswordHash;use App\Domain\Auth\User\User;use App\Domain\Auth\User\UserId;use App\Domain\Auth\User\UserRepository;use App\Infrastructure\Cache\CachedUserRepository;use App\Infrastructure\Cache\RedisCache;use PHPUnit\Framework\TestCase;
final class CachedUserRepositoryTest extends TestCase { public function testLoadsFromInnerThenCacheWithTtl(): void { $user = User::reconstitute(UserId::fromString('u-1'),Email::fromString('u@example.com'),PasswordHash::fromHash('hash'),new \DateTimeImmutable('2026-01-01T00:00:00+00:00')); $inner = new class($user) implements UserRepository { public int $calls=0; public function __construct(private User $user) {} public function nextId(): UserId { return UserId::fromString('n-1'); } public function byEmail(Email $email): ?User { $this->calls++; return $this->user; } public function save(User $user): void {} }; $cache = new class extends RedisCache { public array $items=[]; public ?int $ttl=null; public function __construct() {} public function get(string $key): ?string { return $this->items[$key] ?? null; } public function set(string $key, string $value, ?int $ttlSeconds = null): void { $this->items[$key]=$value; $this->ttl=$ttlSeconds; } public function del(string $key): void { unset($this->items[$key]); } }; $repo = new CachedUserRepository($inner,$cache,123); $repo->byEmail(Email::fromString('u@example.com')); $repo->byEmail(Email::fromString('u@example.com')); self::assertSame(1,$inner->calls); self::assertSame(123,$cache->ttl); }}
